import heapq

def match(orders):
    trades = []
    order_info = {}  # id -> {'side','price','qty','arrival'}
    buy_heap = []   # entries: (-price, arrival, id)
    sell_heap = []  # entries: (price, arrival, id)

    def clean_top(heap):
        while heap:
            top = heap[0]
            oid = top[-1]
            info = order_info.get(oid)
            if info is None or info['qty'] <= 0:
                heapq.heappop(heap)
            else:
                return top
        return None

    def try_match(heap, incoming_side, incoming_id, limit_price, qty):
        while qty > 0:
            top = clean_top(heap)
            if top is None:
                break
            oid = top[-1]
            info = order_info[oid]
            price = info['price']
            if limit_price is not None:
                if incoming_side == 'buy' and price > limit_price:
                    break
                if incoming_side == 'sell' and price < limit_price:
                    break
            trade_qty = min(qty, info['qty'])
            if incoming_side == 'buy':
                trades.append([incoming_id, oid, price, trade_qty])
            else:
                trades.append([oid, incoming_id, price, trade_qty])
            info['qty'] -= trade_qty
            qty -= trade_qty
            if info['qty'] == 0:
                heapq.heappop(heap)
                del order_info[oid]
        return qty

    for arrival, order in enumerate(orders):
        typ = order[0]
        if typ == 'limit':
            _, oid, side, price, qty = order
            if side == 'buy':
                remaining = try_match(sell_heap, 'buy', oid, price, qty)
                if remaining > 0:
                    order_info[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'arrival': arrival}
                    heapq.heappush(buy_heap, (-price, arrival, oid))
            else:
                remaining = try_match(buy_heap, 'sell', oid, price, qty)
                if remaining > 0:
                    order_info[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'arrival': arrival}
                    heapq.heappush(sell_heap, (price, arrival, oid))
        elif typ == 'ioc':
            _, oid, side, price, qty = order
            if side == 'buy':
                try_match(sell_heap, 'buy', oid, price, qty)
            else:
                try_match(buy_heap, 'sell', oid, price, qty)
        elif typ == 'market':
            _, oid, side, qty = order
            if side == 'buy':
                try_match(sell_heap, 'buy', oid, None, qty)
            else:
                try_match(buy_heap, 'sell', oid, None, qty)
        elif typ == 'cancel':
            _, oid = order
            if oid in order_info:
                del order_info[oid]

    return trades

